//! The page's generated TypeScript, written by this test and committed: `webapp/src/gen/solver.ts`, every type
//! reachable from the roots (`visit_roots`) generated by ts-rs from the solver's report and job structs, sorted by name;
//! and `webapp/src/gen/constants.ts`, the model constants (`SOLVER`, serialised from the consts the solver uses, with
//! their type). The test fails when a committed file differs from what the structs give now; `BLESS=1 cargo test --lib
//! ts_gen` writes both instead (as `tests/plan_roll.rs` re-takes its fixture).
use std::any::TypeId;
use std::collections::{BTreeMap, HashSet};
use ts_rs::{Config, TS, TypeVisitor};

/// Where the generated files go.
const GEN_DIR: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/../../webapp/src/gen");

/// What each file says of itself.
const HEADER: &str = "// Generated by ts-rs from the solver's structs (pkg/loopopt/src/ts_gen.rs). Never edit it: change the \
                      Rust and run\n// `BLESS=1 cargo test --lib ts_gen` in pkg/loopopt; the test fails while this \
                      file is stale.\n";

/// Each type's declaration by its TypeScript name, its dependencies visited once each.
struct Declarations<'cfg> {
    cfg: &'cfg Config,
    seen: HashSet<TypeId>,
    by_name: BTreeMap<String, String>,
}

impl TypeVisitor for Declarations<'_> {
    fn visit<T: TS + 'static + ?Sized>(&mut self) {
        // (a primitive or a wrapper has no declaration of its own; ts-rs's own export skips them the same way)
        if T::output_path().is_none() || !self.seen.insert(TypeId::of::<T>()) {
            return;
        }
        let name = T::ident(self.cfg);
        let declaration = format!("{}export {}\n", T::docs().unwrap_or_default(), T::decl(self.cfg));
        // (a generic type is visited once per argument, with one declaration; two types of one name are refused)
        let earlier = self.by_name.insert(name, declaration.clone());
        assert!(earlier.is_none_or(|earlier| earlier == declaration), "two types are named {}", T::ident(self.cfg));
        T::visit_dependencies(self);
    }
}

/// The types the page reads or sends; everything they hold follows.
fn visit_roots(declarations: &mut Declarations) {
    declarations.visit::<crate::loop_planner::output::DeckReply>();
    declarations.visit::<crate::career::reply::CareerReply>();
    declarations.visit::<crate::request::Request>();
    declarations.visit::<crate::request::InitReply>();
}

/// The solver's 64-bit integers are counts and ids well inside a double's exact range.
fn config() -> Config {
    Config::new().with_large_int("number")
}

/// The file's header, then every declaration `visit` reaches, sorted by name.
fn declarations_text(visit: impl FnOnce(&mut Declarations)) -> String {
    let cfg = config();
    let mut declarations = Declarations { cfg: &cfg, seen: HashSet::new(), by_name: BTreeMap::new() };
    visit(&mut declarations);
    let mut text = String::from(HEADER);
    for declaration in declarations.by_name.values() {
        text.push('\n');
        text.push_str(declaration);
    }
    text
}

/// `solver.ts`: every root's declaration and its dependencies'.
fn solver_ts() -> String {
    declarations_text(visit_roots)
}

/// `constants.ts`: `SolverConstants`'s declaration and its dependencies', and `SOLVER`, this build's values.
fn constants_ts() -> String {
    use crate::constants::SolverConstants;
    let values = serde_json::to_string_pretty(&SolverConstants::now()).expect("the constants serialise");
    let declarations = declarations_text(|declarations| declarations.visit::<SolverConstants>());
    format!(
        "{declarations}\n/** the model constants as this build of the solver has them */\nexport const SOLVER: SolverConstants = {values};\n"
    )
}

/// Whether this run writes the files (`BLESS=1`) instead of checking them.
fn blessing() -> bool {
    std::env::var_os("BLESS").is_some_and(|bless| bless == "1")
}

#[test]
fn generated_typescript_is_current() {
    let bless = blessing();
    let mut stale = Vec::new();
    for (name, text) in [("solver.ts", solver_ts()), ("constants.ts", constants_ts())] {
        let path = format!("{GEN_DIR}/{name}");
        if std::fs::read_to_string(&path).is_ok_and(|committed| committed == text) {
            continue;
        }
        if bless {
            std::fs::write(&path, text).unwrap_or_else(|e| panic!("cannot write {path}: {e}"));
            eprintln!("BLESS: wrote {path}");
        } else {
            stale.push(path);
        }
    }
    assert!(stale.is_empty(), "stale generated TypeScript (BLESS=1 cargo test --lib ts_gen rewrites it): {stale:?}");
}
